import{_ as l,a0 as p,w as r,s as o,I as i,x as a,a1 as n,A as t,ao as d}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const P=JSON.parse('{"title":"用 PGP 保護代碼完整性（四）：將主密鑰移到離線存儲中 | LCTT x X-CMD","titleTemplate":false,"description":"用 PGP 保護代碼完整性（四）：將主密鑰移到離線存儲中 | LCTT (201901) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"用 PGP 保護代碼完整性（四）：將主密鑰移到離線存儲中 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"用 PGP 保護代碼完整性（四）：將主密鑰移到離線存儲中 | LCTT (201901) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201901/20180307 Protecting Code Integrity with PGP - Part 4- Moving Your Master Key to Offline Storage","title":"用 PGP 保護代碼完整性（四）：將主密鑰移到離線存儲中","tag":"201901","desc":""},"relativePath":"201901/20180307 Protecting Code Integrity with PGP - Part 4- Moving Your Master Key to Offline Storage.md","filePath":"[post].md"}'),g={name:"201901/20180307 Protecting Code Integrity with PGP - Part 4- Moving Your Master Key to Offline Storage.md"};function u(h,s,k,c,b,f){const e=p("Link");return r(),o("div",null,[s[19]||(s[19]=i("h1",{id:"用-pgp-保護代碼完整性-四-將主密鑰移到離線存儲中",tabindex:"-1"},[a("用 PGP 保護代碼完整性（四）：將主密鑰移到離線存儲中 "),i("a",{class:"header-anchor",href:"#用-pgp-保護代碼完整性-四-將主密鑰移到離線存儲中","aria-label":"Permalink to “用 PGP 保護代碼完整性（四）：將主密鑰移到離線存儲中”"},"​")],-1)),s[20]||(s[20]=i("blockquote",null,[i("p",null,"如果開發者的 PGP 密鑰被偷了，危害非常大。瞭解一下如何更安全。")],-1)),s[21]||(s[21]=i("p",null,[i("img",{src:"https://www.linux.com/sites/lcom/files/styles/rendered_file/public/industry-1920.jpg?itok=gI3QraS8",alt:""})],-1)),s[22]||(s[22]=i("p",null,"在本系列教程中，我們為使用 PGP 提供了一個實用指南。你可以從下面的鏈接中查看前面的文章：",-1)),i("ul",null,[i("li",null,[n(e,{href:"https://linux.cn/article-9524-1.html"},{default:t(()=>[...s[0]||(s[0]=[a("第一部分：基本概念和工具",-1)])]),_:1})]),i("li",null,[n(e,{href:"https://linux.cn/article-9529-1.html"},{default:t(()=>[...s[1]||(s[1]=[a("第二部分：生成你的主密鑰",-1)])]),_:1})]),i("li",null,[n(e,{href:"https://linux.cn/article-9607-1.html"},{default:t(()=>[...s[2]||(s[2]=[a("第三部分：生成 PGP 子密鑰",-1)])]),_:1})])]),s[23]||(s[23]=d(`<p>這是本系列教程的第四部分，我們繼續本教程，我們將談一談如何及為什麼要將主密鑰從你的家目錄移到離線存儲中。現在開始我們的教程。</p><h4 id="清單" tabindex="-1">清單 <a class="header-anchor" href="#清單" aria-label="Permalink to “清單”">​</a></h4><ul><li>準備一個加密的可移除的存儲（必要）</li><li>備份你的 GnuPG 目錄（必要）</li><li>從你的家目錄中刪除主密鑰（推薦）</li><li>從你的家目錄中刪除吊銷證書（推薦）</li></ul><h4 id="考慮事項" tabindex="-1">考慮事項 <a class="header-anchor" href="#考慮事項" aria-label="Permalink to “考慮事項”">​</a></h4><p>為什麼要從你的家目錄中刪除你的主 [C] 密鑰 ？這樣做的主要原因是防止你的主密鑰失竊或意外泄露。對於心懷不軌的人來説，私鑰對他們具有很大的誘惑力 —— 我們知道有幾個惡意軟件成功地實現了掃描用户的家目錄並將發現的私鑰內容上傳。</p><p>對於開發者來説，私鑰失竊是非常危險的事情 —— 在自由軟件的世界中，這無疑是身份證明失竊。從你的家目錄中刪除私鑰將幫你防範這類事件的發生。</p><h4 id="備份你的-gnupg-目錄" tabindex="-1">備份你的 GnuPG 目錄 <a class="header-anchor" href="#備份你的-gnupg-目錄" aria-label="Permalink to “備份你的 GnuPG 目錄”">​</a></h4><p><strong>!!!絕對不要跳過這一步!!!</strong></p><p>備份你的 PGP 密鑰將讓你在需要的時候很容易地恢復它們，這很重要！（這與我們做的使用 paperkey 的災難級備份是不一樣的）。</p><h4 id="準備可移除的加密存儲" tabindex="-1">準備可移除的加密存儲 <a class="header-anchor" href="#準備可移除的加密存儲" aria-label="Permalink to “準備可移除的加密存儲”">​</a></h4><p>我們從取得一個（最好是兩個）小型的 USB “拇指“ 驅動器（可加密 U 盤）開始，我們將用它來做備份。你首先需要去加密它們：</p><p>加密密碼可以使用與主密鑰相同的密碼。</p><h4 id="備份你的-gnupg-目錄-1" tabindex="-1">備份你的 GnuPG 目錄 <a class="header-anchor" href="#備份你的-gnupg-目錄-1" aria-label="Permalink to “備份你的 GnuPG 目錄”">​</a></h4><p>加密過程結束之後，重新插入 USB 驅動器並確保它能夠正常掛載。你可以通過運行 <code>mount</code> 命令去找到設備掛載點的完全路徑。（在 Linux 下，外置介質一般掛載在 <code>/media/disk</code> 下，Mac 一般在它的 <code>/Volumes</code> 下）</p><p>你知道了掛載點的全路徑後，將你的整個 GnuPG 的目錄複製進去：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cp -rp ~/.gnupg [/media/disk/name]/gnupg-backup</span></span></code></pre></div><p>（注意：如果出現任何套接字不支持的錯誤，沒有關係，直接忽略它們。）</p><p>現在，用如下的命令去測試一下，確保它們能夠正常地工作：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ gpg --homedir=[/media/disk/name]/gnupg-backup --list-key [fpr]</span></span></code></pre></div><p>如果沒有出現任何錯誤，説明一切正常。彈出這個 USB 驅動器並給它粘上一個明確的標籤，以便於你下次需要它時能夠很快找到它。接着，將它放到一個安全的 —— 但不要太遠 —— 的地方，因為從現在起，你需要偶爾使用它來做一些像編輯身份信息、添加或吊銷子證書、或簽署其它人的密鑰這樣的事情。</p><h4 id="刪除主密鑰" tabindex="-1">刪除主密鑰 <a class="header-anchor" href="#刪除主密鑰" aria-label="Permalink to “刪除主密鑰”">​</a></h4><p>我們家目錄中的文件並沒有像我們所想像的那樣受到保護。它們可能會通過許多不同的方式被泄露或失竊：</p><ul><li>通過快速複製來配置一個新工作站時的偶爾事故</li><li>通過系統管理員的疏忽或惡意操作</li><li>通過安全性欠佳的備份</li><li>通過桌面應用中的惡意軟件（瀏覽器、pdf 查看器等等）</li><li>通過跨境脅迫</li></ul><p>使用一個很好的密碼來保護你的密鑰是降低上述風險的一個很好方法，但是密碼能夠通過鍵盤記錄器、背後窺視、或其它方式被發現。基於以上原因，我們建議去配置一個從你的家目錄上可移除的主密鑰，將它保存在一個離線存儲中。</p><h5 id="刪除你的主密鑰" tabindex="-1">刪除你的主密鑰 <a class="header-anchor" href="#刪除你的主密鑰" aria-label="Permalink to “刪除你的主密鑰”">​</a></h5><p><strong>請查看前面的節，確保你有完整的你的 GnuPG 目錄的一個備份。如果你沒有一個可用的備份，下面所做的操作將會使你的主密鑰失效！！！</strong></p><p>首先，識別你的主密鑰的 keygrip：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ gpg --with-keygrip --list-key [fpr]</span></span></code></pre></div><p>它的輸出應該像下面這樣：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>pub   rsa4096 2017-12-06 [C] [expires: 2019-12-06]</span></span>
<span class="line"><span>     111122223333444455556666AAAABBBBCCCCDDDD</span></span>
<span class="line"><span>     Keygrip = AAAA999988887777666655554444333322221111</span></span>
<span class="line"><span>uid           [ultimate] Alice Engineer &lt;alice@example.org&gt;</span></span>
<span class="line"><span>uid           [ultimate] Alice Engineer &lt;allie@example.net&gt;</span></span>
<span class="line"><span>sub   rsa2048 2017-12-06 [E]</span></span>
<span class="line"><span>     Keygrip = BBBB999988887777666655554444333322221111</span></span>
<span class="line"><span>sub   rsa2048 2017-12-06 [S]</span></span>
<span class="line"><span>     Keygrip = CCCC999988887777666655554444333322221111</span></span></code></pre></div><p>找到 <code>pub</code> 行下方的 <code>Keygrip</code> 條目（就在主密鑰指紋的下方）。它與你的家目錄下 <code>.gnupg</code> 目錄下的一個文件是一致的：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cd ~/.gnupg/private-keys-v1.d</span></span>
<span class="line"><span>$ ls</span></span>
<span class="line"><span>AAAA999988887777666655554444333322221111.key</span></span>
<span class="line"><span>BBBB999988887777666655554444333322221111.key</span></span>
<span class="line"><span>CCCC999988887777666655554444333322221111.key</span></span></code></pre></div><p>現在你做的全部操作就是簡單地刪除與主密鑰 keygrip 一致的 <code>.key</code> 文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cd ~/.gnupg/private-keys-v1.d</span></span>
<span class="line"><span>$ rm AAAA999988887777666655554444333322221111.key</span></span></code></pre></div><p>現在，如果運行 <code>--list-secret-keys</code> 命令將出現問題，它將顯示主密鑰丟失（<code>#</code> 表示不可用）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ gpg --list-secret-keys</span></span>
<span class="line"><span>sec# rsa4096 2017-12-06 [C] [expires: 2019-12-06]</span></span>
<span class="line"><span> 111122223333444455556666AAAABBBBCCCCDDDD</span></span>
<span class="line"><span>uid [ultimate] Alice Engineer &lt;alice@example.org&gt;</span></span>
<span class="line"><span>uid [ultimate] Alice Engineer &lt;allie@example.net&gt;</span></span>
<span class="line"><span>ssb rsa2048 2017-12-06 [E]</span></span>
<span class="line"><span>ssb rsa2048 2017-12-06 [S]</span></span></code></pre></div><h4 id="刪除吊銷證書" tabindex="-1">刪除吊銷證書 <a class="header-anchor" href="#刪除吊銷證書" aria-label="Permalink to “刪除吊銷證書”">​</a></h4><p>你應該去刪除的另一個文件是吊銷證書（<strong>刪除之前，確保你的備份中有它</strong>），它是使用你的主密鑰自動創建的。吊銷證書允許一些人去永久標記你的證書為吊銷狀態，這意味着它無論在任何用途中將不再被使用或信任。一般是使用它來吊銷由於某些原因不再受控的一個密鑰 —— 比如，你丟失了密鑰密碼。</p><p>與使用主密鑰一樣，如果一個吊銷證書泄露到惡意者手中，他們能夠使用它去破壞你的開發者數字身份，因此，最好是從你的家目錄中刪除它。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cd ~/.gnupg/openpgp-revocs.d</span></span>
<span class="line"><span>rm [fpr].rev</span></span></code></pre></div><p>在下一篇文章中，你將學習如何保護你的子密鑰。敬請期待。</p>`,41)),i("p",null,[s[4]||(s[4]=a("從來自 Linux 基金會和 edX 的免費課程 ",-1)),n(e,{href:"https://training.linuxfoundation.org/linux-courses/system-administration-training/introduction-to-linux"},{default:t(()=>[...s[3]||(s[3]=[a("“Linux 入門”",-1)])]),_:1}),s[5]||(s[5]=a(" 中學習更多 Linux 知識。",-1))]),s[24]||(s[24]=i("hr",null,null,-1)),i("p",null,[s[7]||(s[7]=a("via: ",-1)),n(e,{href:"https://www.linux.com/blog/learn/pgp/2018/3/protecting-code-integrity-pgp-part-4-moving-your-master-key-offline-storage"},{default:t(()=>[...s[6]||(s[6]=[a("https://www.linux.com/blog/learn/pgp/2018/3/protecting-code-integrity-pgp-part-4-moving-your-master-key-offline-storage",-1)])]),_:1})]),i("p",null,[s[11]||(s[11]=a("作者：",-1)),n(e,{href:"https://www.linux.com/users/mricon"},{default:t(()=>[...s[8]||(s[8]=[a("Konstantin Ryabitsev",-1)])]),_:1}),s[12]||(s[12]=a(" 譯者：",-1)),n(e,{href:"https://github.com/qhwdw"},{default:t(()=>[...s[9]||(s[9]=[a("qhwdw",-1)])]),_:1}),s[13]||(s[13]=a(" 校對：",-1)),n(e,{href:"https://github.com/wxy"},{default:t(()=>[...s[10]||(s[10]=[a("wxy",-1)])]),_:1})]),i("p",null,[s[16]||(s[16]=a("本文由 ",-1)),n(e,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[14]||(s[14]=[a("LCTT",-1)])]),_:1}),s[17]||(s[17]=a(" 原創編譯，",-1)),n(e,{href:"https://linux.cn/"},{default:t(()=>[...s[15]||(s[15]=[a("Linux中國",-1)])]),_:1}),s[18]||(s[18]=a(" 榮譽推出",-1))])])}const C=l(g,[["render",u]]);export{P as __pageData,C as default};
